# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet = `GET /ueditor/net/controller.ashx?action=catchimage&encode=utf-8 HTTP/1.1
Host: {{params(target)}}
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8
Accept-Language: zh-CN,zh;q=0.8,zh-TW;q=0.7,zh-HK;q=0.5,en-US;q=0.3,en;q=0.2
Connection: close
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/102.0.0.0 Safari/537.36
`

    check=func(rsp,header,body){
        if str.MatchAnyOfSubString(header, `HTTP/1.1 200 OK`)&& str.MatchAnyOfSubString(body,`没有指定抓取源`){
            return true
        }
        return false
    }

    Type="文件上传"
    severity="critical"
    reference="ueditor编辑器-cnvd-2017-20077 文件上传漏洞"


    resp,req,_ = poc.HTTP(packet, 
    poc.params({"target":addr}),
    poc.https(isTls),
    poc.redirectTimes(0),
    )


    header, body = poc.Split(resp)
    respIns, _ = poc.ParseBytesToHTTPResponse(resp)
    urlIns, _ = str.ExtractURLFromHTTPRequestRaw(req, isTls)
    url = urlIns.String()
    // dump(resp)


    if check(respIns, header, body){
            yakit.Info("FOUND INFO for %v", typeVerbose)
            risk.NewRisk(
                url, risk.severity(severity), 
                risk.title(sprintf("FOUND %v", typeVerbose)),
                risk.titleVerbose(sprintf("%v", reference)),
                risk.type(Type), risk.typeVerbose(Type),
                risk.details({
                    "request": req,
                    "response": resp,
                    "url": url,
                }),
            )
        }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }

}
